Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
accel/amdxdna: Fix runtime suspend deadlock when there is
 pending job

The runtime suspend callback drains the running job workqueue before
suspending the device. If a job is still executing and calls
pm_runtime_resume_and_get(), it can deadlock with the runtime suspend
path.

Fix this by moving pm_runtime_resume_and_get() from the job execution
routine to the job submission routine, ensuring the device is resumed
before the job is queued and avoiding the deadlock during runtime
suspend.

Fixes: 063db451832b ("accel/amdxdna: Enhance runtime power management")
Reviewed-by: Mario Limonciello (AMD) <superm1@kernel.org>
Signed-off-by: Lizhi Hou <lizhi.hou@amd.com>
Link: https://patch.msgid.link/20260310180058.336348-1-lizhi.hou@amd.com

Here is the root cause:
The deadlock occurs because `pm_runtime_resume_and_get()` was called inside `aie2_sched_job_run()` (the job execution routine). When the runtime suspend callback (`amdxdna_runtime_suspend`) drains the job workqueue by calling `drm_sched_stop()`, it holds the runtime PM lock. If a job is executing and calls `pm_runtime_resume_and_get()`, that function tries to acquire the same lock, leading to a deadlock. Moving the PM resume call to the job submission path (`amdxdna_cmd_submit()`) ensures the device is active before the job is queued, avoiding the lock contention during suspend.

Here is the patch:

 static void
 aie2_sched_notify(struct amdxdna_sched_job *job)
 {
 	struct dma_fence *fence = job->fence;

 	trace_xdna_job(&job->base, job->hwctx->name, "signaled fence", job->seq);

-	amdxdna_pm_suspend_put(job->hwctx->client->xdna);
 	job->hwctx->priv->completed++;
 	dma_fence_signal(fence);

 	up(&job->hwctx->priv->job_sem);
 	job->job_done = true;
 	mmput_async(job->mm);
 	aie2_job_put(job);
 }


 static struct dma_fence *
 aie2_sched_job_run(struct drm_sched_job *sched_job)
 {
 	struct amdxdna_sched_job *job = drm_job_to_xdna_job(sched_job);
 	struct amdxdna_gem_obj *cmd_abo = job->cmd_bo;
 	struct amdxdna_hwctx *hwctx = job->hwctx;
 	struct dma_fence *fence;
 	int ret;

-	ret = amdxdna_pm_resume_get(hwctx->client->xdna);
-	if (ret)
+	if (!hwctx->priv->mbox_chann)
 		return NULL;

-	if (!hwctx->priv->mbox_chann) {
-		amdxdna_pm_suspend_put(hwctx->client->xdna);
-		return NULL;
-	}
-
-	if (!mmget_not_zero(job->mm)) {
-		amdxdna_pm_suspend_put(hwctx->client->xdna);
+	if (!mmget_not_zero(job->mm))
 		return ERR_PTR(-ESRCH);
-	}

 	kref_get(&job->refcnt);
 	fence = dma_fence_get(job->fence);

 	if (job->drv_cmd) {
 		switch (job->drv_cmd->opcode) {
 		case SYNC_DEBUG_BO:
 			ret = aie2_sync_bo(hwctx, job, aie2_sched_drvcmd_resp_handler);
 			break;
 		case ATTACH_DEBUG_BO:
 			ret = aie2_config_debug_bo(hwctx, job, aie2_sched_drvcmd_resp_handler);
 			break;
 		default:
 			ret = -EINVAL;
 			break;
 		}
 		goto out;
 	}

 	amdxdna_cmd_set_state(cmd_abo, ERT_CMD_STATE_NEW);

 	if (amdxdna_cmd_get_op(cmd_abo) == ERT_CMD_CHAIN)
 		ret = aie2_cmdlist_multi_execbuf(hwctx, job, aie2_sched_cmdlist_resp_handler);
 	else if (force_cmdlist)
 		ret = aie2_cmdlist_single_execbuf(hwctx, job, aie2_sched_cmdlist_resp_handler);
 	else
 		ret = aie2_execbuf(hwctx, job, aie2_sched_resp_handler);

 out:
 	if (ret) {
-		amdxdna_pm_suspend_put(hwctx->client->xdna);
 		dma_fence_put(job->fence);
 		aie2_job_put(job);
 		mmput(job->mm);
 		fence = ERR_PTR(ret);
 	}
 	trace_xdna_job(sched_job, hwctx->name, "sent to device", job->seq);

 	return fence;
 }



